/*
 * A191117  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x-2 and 4x+2 are in a.
 * https://oeis.org/A191117
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   sequence generated by a(1)=1 and for each x in the sequence add
 *            3x-2 and 4x+2
 * Range:     u8 n <= 6, u16 n <= 271, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

typedef struct {
    seq_t *data;
    size_t size;
    size_t cap;
} heap_t;

/* Push a value onto the min-heap */
static void heap_push(heap_t *h, seq_t val) {
    if (h->size == h->cap) {
        size_t newcap = h->cap ? h->cap * 2 : 16;
        h->data = (seq_t *)realloc(h->data, newcap * sizeof(seq_t));
        h->cap = newcap;
    }
    h->data[h->size++] = val;

    /* bubble up */
    size_t i = h->size - 1;
    while (i > 0) {
        size_t p = (i - 1) / 2;
        if (h->data[p] <= h->data[i]) break;
        seq_t t = h->data[i];
        h->data[i] = h->data[p];
        h->data[p] = t;
        i = p;
    }
}

/* Pop the minimum value from the heap */
static seq_t heap_pop(heap_t *h) {
    seq_t top = h->data[0];
    h->size--;
    if (h->size > 0) {
        h->data[0] = h->data[h->size];
        /* bubble down */
        size_t i = 0;
        while (1) {
            size_t l = 2 * i + 1;
            size_t r = l + 1;
            if (l >= h->size) break;
            size_t smallest = l;
            if (r < h->size && h->data[r] < h->data[l]) smallest = r;
            if (h->data[i] <= h->data[smallest]) break;
            seq_t t = h->data[i];
            h->data[i] = h->data[smallest];
            h->data[smallest] = t;
            i = smallest;
        }
    }
    return top;
}

seq_t a(idx_t n) {
    /* static state to maintain progress across calls */
    static heap_t heap = {NULL, 0, 0};
    static seq_t *terms = NULL;
    static size_t terms_cap = 0, terms_len = 0;
    static int initialized = 0;

    if (!initialized) {
        /* seed the generator */
        heap_push(&heap, 1);
        initialized = 1;
    }

    /* generate terms until we have at least n of them */
    while (terms_len < n) {
        seq_t x = heap_pop(&heap);

        /* skip duplicates: only new terms are stored */
        if (terms_len == 0 || x != terms[terms_len - 1]) {
            /* ensure space in array */
            if (terms_len == terms_cap) {
                size_t newcap = terms_cap ? terms_cap * 2 : 16;
                terms = (seq_t *)realloc(terms, newcap * sizeof(seq_t));
                terms_cap = newcap;
            }
            terms[terms_len++] = x;

            /* generate children of the new term */
            seq_t c1 = 3 * x - 2;
            seq_t c2 = 4 * x + 2;
            heap_push(&heap, c1);
            heap_push(&heap, c2);
        }
    }

    return terms[n - 1];
}
